import React, { useEffect, useMemo, useState } from 'react';
import { ArrowLeft, Check, ChevronRight, Loader2, Search } from 'lucide-react';
import { useQueryClient } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import { Badge } from '@/components/ui/badge';

// Generated by graphql-codegen (typescript-react-query plugin) from
// graphql/operations/permissions.graphql and school-users.graphql.
// Adjust this import path to wherever your codegen output lands
// (codegen.yml `generates` target) — commonly src/generated/graphql.ts.
import {
  useGetMembershipQuery,
  useGetPermissionsQuery,
  useGetSchoolMembershipsQuery,
  useUpdateSchoolUserPermissionsMutation,
} from '@stackschool/ui';
import { useDebounce } from '@/hooks/useDebounce';
import { ROLE_BADGE_CLASS } from '@/constant';
import {
  PermissionAction,
  PermissionModule,
  ROLE_LABEL_FR,
} from '@stackschool/contracts';
import { cn } from '@/lib/utils';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Label } from '@/components/ui/label';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { useWindowSize } from 'react-use';
import { useIsMobile } from '@/hooks/use-mobile';
import { ScrollArea } from '@/components/ui/scroll-area';

const MODULE_LABEL_FR: Record<PermissionModule, string> = {
  ATTENDANCE: 'Présences',
  ACADEMICS: 'Pédagogie',
  USERS: 'Utilisateurs',
  FINANCE: 'Finances',
  SETTINGS: "Paramètres de l'école",
};

const MODULE_ORDER: PermissionModule[] = [
  'ATTENDANCE',
  'ACADEMICS',
  'USERS',
  'FINANCE',
  'SETTINGS',
];

const ACTION_BADGE_CLASS: Record<PermissionAction, string> = {
  MANAGE: 'bg-violet-100 text-violet-700',
  CREATE: 'bg-emerald-100 text-emerald-700',
  READ: 'bg-slate-100 text-slate-600',
  UPDATE: 'bg-amber-100 text-amber-700',
  DELETE: 'bg-rose-100 text-rose-700',
  MARK: 'bg-sky-100 text-sky-700',
  PUBLISH: 'bg-indigo-100 text-indigo-700',
  EXPORT: 'bg-teal-100 text-teal-700',
};

const ACTION_LABEL_FR: Record<PermissionAction, string> = {
  MANAGE: 'GÉRER',
  CREATE: 'CRÉER',
  READ: 'LIRE',
  UPDATE: 'MODIFIER',
  DELETE: 'SUPPRIMER',
  MARK: 'MARQUER',
  PUBLISH: 'PUBLIER',
  EXPORT: 'EXPORTER',
};

const UpdateSchoolUserPermissionSchema = z.object({
  schoolUserId: z.uuid(),
  grantPermissionIds: z.array(z.string()).optional(),
  revokePermissionIds: z.array(z.string()).optional(),
});

export type UpdateSchoolUserPermissionSchema = z.infer<
  typeof UpdateSchoolUserPermissionSchema
>;

export function PermissionsPane() {
  const [query, setQuery] = useState('');
  const debouncedQuery = useDebounce(query, 300);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [draft, setDraft] = useState<Set<string>>(new Set());
  const [dirty, setDirty] = useState(false);
  const [justSaved, setJustSaved] = useState(false);
  const [showEditor, setShowEditor] = useState(false);
  const isMobile = useIsMobile();
  const { width } = useWindowSize();

  const { control } = useForm<UpdateSchoolUserPermissionSchema>({
    resolver: zodResolver(UpdateSchoolUserPermissionSchema),
    mode: 'onChange',
  });

  const queryClient = useQueryClient();

  const { data: catalogData, isLoading: catalogLoading } =
    useGetPermissionsQuery(undefined, {
      staleTime: Infinity,
    });
  const permissions = catalogData?.permissions ?? [];

  const permissionGroups = useMemo(() => {
    return MODULE_ORDER.map((moduleId) => ({
      id: moduleId,
      label: MODULE_LABEL_FR[moduleId],
      permissions: permissions.filter((p) => p.module === moduleId),
    })).filter((g) => g.permissions.length > 0);
  }, [permissions]);

  const { data: listData, isLoading: listLoading } =
    useGetSchoolMembershipsQuery({
      input: {
        searchTerm: debouncedQuery || undefined,
      },
    });
  const schoolUsers = listData?.getMemberships ?? [];

  // Default to the first result on desktop only, while mobile starts on the search/list view.
  useEffect(() => {
    if (isMobile || schoolUsers.length === 0) return;
    if (!selectedId && schoolUsers.length > 0) {
      setSelectedId(schoolUsers?.[0]?.id);
    }
  }, [schoolUsers, selectedId, isMobile]);

  // Detail — only fires for the selected user.
  const {
    data: detailData,
    isLoading: detailLoading,
    isFetching: detailFetching,
  } = useGetMembershipQuery({ id: selectedId }, { enabled: !!selectedId });
  const selectedUser = detailData?.membership;

  // Re-seed the draft whenever the selected user's server data changes
  // (initial load, switching users, or after a save invalidates it).
  useEffect(() => {
    if (selectedUser) {
      setDraft(new Set(selectedUser.permissions?.map((p) => p?.id)));
      setDirty(false);
      setJustSaved(false);
    }
  }, [selectedUser]);

  const updatePermissions = useUpdateSchoolUserPermissionsMutation({
    onSuccess: async () => {
      await queryClient.invalidateQueries({
        queryKey: ['GetMembership', { id: selectedId }],
      });
      setDirty(false);
      setJustSaved(true);
    },
  });

  function togglePermission(id: string) {
    console.log('togglePermission', id);
    setDraft((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
    setDirty(true);
    setJustSaved(false);
  }

  function toggleGroup(group: (typeof permissionGroups)[0]) {
    const ids = group.permissions.map((p) => p.id);
    const allOn = ids.every((id) => draft.has(id));
    setDraft((prev) => {
      const next = new Set(prev);
      ids.forEach((id) => (allOn ? next.delete(id) : next.add(id)));
      return next;
    });
    setDirty(true);
    setJustSaved(false);
  }

  function handleSave() {
    if (!selectedUser) return;
    const originalIds = new Set<string>(
      selectedUser.permissions?.map((p) => p?.id ?? ''),
    );
    const grantPermissionIds = [...draft].filter((id) => !originalIds.has(id));
    const revokePermissionIds = [...originalIds].filter((id) => !draft.has(id));

    updatePermissions.mutate({
      input: {
        schoolUserId: selectedUser.id,
        grantPermissionIds,
        revokePermissionIds,
      },
    });
  }

  return (
    <div className="flex h-full min-h-0 w-full gap-2 overflow-hidden">
      {isMobile ? (
        <div className="relative flex h-full min-h-0 w-full overflow-hidden rounded-lg border">
          <div
            className={cn(
              ' flex w-full flex-col transition-all duration-300 ease-out',
              showEditor
                ? 'pointer-events-none translate-x-[-105%] opacity-0'
                : 'translate-x-0 opacity-100',
            )}
          >
            <div className="flex items-center gap-2 border-b px-3 py-2.5">
              <Search className="h-4 w-4" />
              <Input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Rechercher un utilisateur…"
                className="h-auto border-0 p-0 bg-transparent! text-sm shadow-none focus-visible:ring-0"
              />
            </div>
            <div className="min-h-0 flex-1 overflow-y-auto scroll-fade scrollbar-none">
              <div className="flex flex-col gap-0.5 p-2">
                {listLoading && (
                  <div className="flex items-center justify-center py-8 ">
                    <Loader2 className="h-4 w-4 animate-spin" />
                  </div>
                )}
                {!listLoading &&
                  schoolUsers.length > 0 &&
                  schoolUsers.map((u) => (
                    <button
                      key={u?.id}
                      onClick={() => {
                        setSelectedId(u?.id!);
                        setShowEditor(true);
                      }}
                      className={
                        'flex w-full items-center gap-2.5 rounded-md px-2 py-2 text-left transition-colors duration-300 ' +
                        (u?.id === selectedId
                          ? 'bg-secondary'
                          : 'hover:bg-secondary')
                      }
                    >
                      <Avatar className="flex h-10 w-10">
                        <AvatarImage
                          src={u?.schoolProfile?.avatarUrl ?? undefined}
                        />
                        <AvatarFallback className="bg-secondary">
                          {u?.schoolProfile?.lastName?.[0]}{' '}
                          {u?.schoolProfile?.firstName?.[0]}
                        </AvatarFallback>
                      </Avatar>
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-medium">
                          {u?.schoolProfile?.lastName}{' '}
                          {u?.schoolProfile?.firstName}
                        </span>
                        <span className="block truncate text-xs">
                          {u?.user?.email || u?.user?.phoneNumber}
                        </span>
                      </span>
                      <Badge
                        className={
                          'flex-shrink-0 text-[10.5px] font-normal ' +
                          ROLE_BADGE_CLASS[u?.role!]
                        }
                      >
                        {ROLE_LABEL_FR[u?.role!] ?? u?.role}
                      </Badge>
                      <ChevronRight className="h-4 w-4 flex-shrink-0" />
                    </button>
                  ))}
                {!listLoading && schoolUsers.length === 0 && (
                  <p className="px-3 py-4 text-sm ">
                    Aucun utilisateur ne correspond.
                  </p>
                )}
              </div>
            </div>
          </div>

          <div
            className={cn(
              'absolute inset-0 flex h-full min-h-0 w-full flex-col transition-all duration-300 ease-out',
              showEditor
                ? 'translate-x-0 opacity-100'
                : 'pointer-events-none translate-x-[105%] opacity-0',
            )}
          >
            <div className="flex h-full min-h-0 flex-col">
              <div className="mb-4 flex items-center justify-between border-b px-2 py-2">
                <div className="flex items-center gap-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      setShowEditor(false);
                    }}
                    className="h-8 px-2"
                  >
                    <ArrowLeft className="mr-1 h-4 w-4" />
                    Retour
                  </Button>
                </div>
                <Button
                  onClick={handleSave}
                  disabled={!dirty || updatePermissions.isPending}
                  className=""
                >
                  {updatePermissions.isPending ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : justSaved ? (
                    <>
                      <Check className="mr-1.5 h-4 w-4" /> Enregistré
                    </>
                  ) : (
                    'Enregistrer'
                  )}
                </Button>
              </div>

              {(detailLoading || catalogLoading) && selectedId && (
                <div className="flex items-center gap-2 p-2 text-sm">
                  <Loader2 className="h-4 w-4 animate-spin" /> Chargement…
                </div>
              )}

              {!detailLoading && selectedUser && (
                <>
                  {/* Header name and button */}
                  <div className="mb-5 flex flex-col gap-1 px-2">
                    <h3 className="text-sm lg:text-xl font-semibold text-primary">
                      {selectedUser.schoolProfile?.firstName}{' '}
                      {selectedUser.schoolProfile?.lastName}
                    </h3>
                    <p className="text-sm">
                      {selectedUser.user?.email ||
                        selectedUser?.user?.phoneNumber}{' '}
                      · rôle :{' '}
                      {ROLE_LABEL_FR[selectedUser.role] ?? selectedUser.role}
                      {detailFetching && ' · actualisation…'}
                    </p>
                  </div>

                  {updatePermissions.isError && (
                    <p className="mb-3 text-sm text-rose-600">
                      Échec de l'enregistrement — réessayez.
                    </p>
                  )}

                  <ScrollArea className="min-h-0 flex-1 overflow-y-auto scroll-fade-t px-2">
                    <div className="flex flex-col gap-2 space-y-3">
                      {permissionGroups.map((group) => {
                        const ids = group.permissions.map((p) => p.id);
                        const activeCount = ids.filter((id) =>
                          draft.has(id),
                        ).length;
                        const allOn = activeCount === ids.length;
                        const someOn = activeCount > 0 && !allOn;

                        return (
                          <div
                            key={group.id}
                            className="rounded-lg border mt-2"
                          >
                            <div className="flex items-center justify-between border-b px-3.5 py-2.5">
                              <Label className="flex cursor-pointer items-center gap-2.5">
                                <Checkbox
                                  checked={someOn ? 'indeterminate' : allOn}
                                  onCheckedChange={() => toggleGroup(group)}
                                />
                                <span className="text-sm font-semibold ">
                                  {group.label}
                                </span>
                              </Label>
                              <span className="text-xs">
                                {activeCount}/{ids.length}
                              </span>
                            </div>
                            <div className="flex flex-col gap-1 px-3.5 py-2">
                              {group.permissions.map((perm) => (
                                <Label
                                  key={perm.id}
                                  className="flex cursor-pointer items-start gap-2.5 py-1.5 text-sm "
                                >
                                  <Checkbox
                                    className="mt-0.5"
                                    checked={draft.has(perm.id)}
                                    onCheckedChange={() =>
                                      togglePermission(perm.id)
                                    }
                                  />
                                  <span className="min-w-0 flex-1">
                                    <span className="flex flex-wrap items-center gap-2">
                                      <span>{perm.name}</span>
                                      <Badge
                                        className={
                                          'shrink-0 text-[9px] font-medium tracking-wide ' +
                                          ACTION_BADGE_CLASS[perm.action]
                                        }
                                      >
                                        {ACTION_LABEL_FR[perm.action]}
                                      </Badge>
                                    </span>
                                    <span className="block font-mono text-[10px]">
                                      {perm.action}:{perm.subject}
                                    </span>
                                    {perm.description && (
                                      <span className="block text-xs">
                                        {perm.description}
                                      </span>
                                    )}
                                  </span>
                                </Label>
                              ))}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </ScrollArea>
                </>
              )}
            </div>
          </div>
        </div>
      ) : (
        <>
          {/* User list */}
          <div className="flex w-72 flex-shrink-0 flex-col rounded-lg border">
            <div className="flex items-center gap-2 border-b px-3 py-2.5">
              <Search className="h-4 w-4" />
              <Input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Rechercher un utilisateur…"
                className="h-auto border-0 p-0 bg-transparent! text-sm shadow-none focus-visible:ring-0"
              />
            </div>
            <div className="min-h-0 flex-1 overflow-y-auto scroll-fade scrollbar-none">
              <div className="flex flex-col gap-0.5 p-2">
                {listLoading && (
                  <div className="flex items-center justify-center py-8 ">
                    <Loader2 className="h-4 w-4 animate-spin" />
                  </div>
                )}
                {!listLoading &&
                  schoolUsers.length > 0 &&
                  schoolUsers.map((u) => (
                    <button
                      key={u?.id}
                      onClick={() => {
                        setSelectedId(u?.id!);
                        setShowEditor(true);
                      }}
                      className={
                        'flex w-full items-center gap-2.5 rounded-md px-2 py-2 text-left transition-colors ' +
                        (u?.id === selectedId
                          ? 'bg-secondary'
                          : 'hover:bg-secondary')
                      }
                    >
                      <Avatar className="flex h-10 w-10">
                        <AvatarImage
                          src={u?.schoolProfile?.avatarUrl ?? undefined}
                        />
                        <AvatarFallback className="bg-secondary">
                          {u?.schoolProfile?.lastName?.[0]}{' '}
                          {u?.schoolProfile?.firstName?.[0]}
                        </AvatarFallback>
                      </Avatar>
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-medium">
                          {u?.schoolProfile?.lastName}{' '}
                          {u?.schoolProfile?.firstName}
                        </span>
                        <span className="block truncate text-xs">
                          {u?.user?.email || u?.user?.phoneNumber}
                        </span>
                      </span>
                      <Badge
                        className={
                          'flex-shrink-0 text-[10.5px] font-normal ' +
                          ROLE_BADGE_CLASS[u?.role!]
                        }
                      >
                        {ROLE_LABEL_FR[u?.role!] ?? u?.role}
                      </Badge>
                      <ChevronRight className="h-4 w-4 flex-shrink-0" />
                    </button>
                  ))}
                {!listLoading && schoolUsers.length === 0 && (
                  <p className="px-3 py-4 text-sm ">
                    Aucun utilisateur ne correspond.
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Detail / editor */}
          <div className="min-w-0 flex-1 min-h-0 overflow-hidden">
            {(detailLoading || catalogLoading) && selectedId && (
              <div className="flex items-center gap-2 text-sm">
                <Loader2 className="h-4 w-4 animate-spin" /> Chargement…
              </div>
            )}

            {!detailLoading && selectedUser && (
              <div className="flex h-full min-h-0 flex-col">
                <div className="mb-5 flex items-start justify-between px-2">
                  <div>
                    <h3 className="text-sm lg:text-xl font-semibold text-primary">
                      {selectedUser.schoolProfile?.firstName}{' '}
                      {selectedUser.schoolProfile?.lastName}
                    </h3>
                    <p className="text-sm">
                      {selectedUser.user?.email ||
                        selectedUser?.user?.phoneNumber}{' '}
                      · rôle :{' '}
                      {ROLE_LABEL_FR[selectedUser.role] ?? selectedUser.role}
                      {detailFetching && ' · actualisation…'}
                    </p>
                  </div>
                  <Button
                    onClick={handleSave}
                    disabled={!dirty || updatePermissions.isPending}
                    className=""
                  >
                    {updatePermissions.isPending ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : justSaved ? (
                      <>
                        <Check className="mr-1.5 h-4 w-4" /> Enregistré
                      </>
                    ) : (
                      'Enregistrer'
                    )}
                  </Button>
                </div>

                {updatePermissions.isError && (
                  <p className="mb-3 text-sm text-rose-600">
                    Échec de l'enregistrement — réessayez.
                  </p>
                )}

                <div className="min-h-0 flex-1 overflow-y-auto scroll-fade-t">
                  <div className="flex flex-col gap-2 space-y-3">
                    {permissionGroups.map((group) => {
                      const ids = group.permissions.map((p) => p.id);
                      const activeCount = ids.filter((id) =>
                        draft.has(id),
                      ).length;
                      const allOn = activeCount === ids.length;
                      const someOn = activeCount > 0 && !allOn;

                      return (
                        <div key={group.id} className="rounded-lg border mt-2">
                          <div className="flex items-center justify-between border-b px-3.5 py-2.5">
                            <Label className="flex cursor-pointer items-center gap-2.5">
                              <Checkbox
                                checked={someOn ? 'indeterminate' : allOn}
                                onCheckedChange={() => toggleGroup(group)}
                              />
                              <span className="text-sm font-semibold ">
                                {group.label}
                              </span>
                            </Label>
                            <span className="text-xs">
                              {activeCount}/{ids.length}
                            </span>
                          </div>
                          <div className="flex flex-col gap-1 px-3.5 py-2">
                            {group.permissions.map((perm) => (
                              <Label
                                key={perm.id}
                                className="flex cursor-pointer items-start gap-2.5 py-1.5 text-sm "
                              >
                                <Checkbox
                                  className="mt-0.5"
                                  checked={draft.has(perm.id)}
                                  onCheckedChange={() =>
                                    togglePermission(perm.id)
                                  }
                                />
                                <span className="min-w-0 flex-1">
                                  <span className="flex flex-wrap items-center gap-2">
                                    <span>{perm.name}</span>
                                    <Badge
                                      className={
                                        'shrink-0 text-[9px] font-medium tracking-wide ' +
                                        ACTION_BADGE_CLASS[perm.action]
                                      }
                                    >
                                      {ACTION_LABEL_FR[perm.action]}
                                    </Badge>
                                  </span>
                                  <span className="block font-mono text-[10px]">
                                    {perm.action}:{perm.subject}
                                  </span>
                                  {perm.description && (
                                    <span className="block text-xs">
                                      {perm.description}
                                    </span>
                                  )}
                                </span>
                              </Label>
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}
